INSERT INTO `areaclic` VALUES ('mdPBiceps','Prega cutnea do bceps','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea do b\\\'edceps\\plain\\f3\\fs22 \r\n\\par \r\n\\par Deve ser medida na parte anterior do antebra\\\'e7o, sobre a maior eleva\\\'e7\\\'e3o do m\\\'fasculo b\\\'edceps, aplicando-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e, sem soltar, faz-se 3 leituras, utilizando a m\\\'e9dia das 2 mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',4);
